#!/usr/bin/env bash
set -euo pipefail

tmpdir="$(mktemp -d)"
cat > "$tmpdir/BusyDemo.java" <<'JAVA'
public class BusyDemo {
    public static void main(String[] args) throws Exception {
        Thread hot = new Thread(() -> {
            long x = 0;
            while (!Thread.currentThread().isInterrupted()) {
                x += System.nanoTime() & 7;
                if ((x & 0x3fffff) == 0) {
                    Thread.yield();
                }
            }
        }, "hot-loop-demo");
        hot.start();
        Thread.sleep(15000);
    }
}
JAVA

javac "$tmpdir/BusyDemo.java"
java -Xms64m -Xmx64m -cp "$tmpdir" BusyDemo &
pid="$!"
trap 'kill "$pid" 2>/dev/null || true' EXIT
sleep 1

jcmd "$pid" VM.flags | sed -n '1,5p'
jcmd "$pid" GC.heap_info | sed -n '1,10p'
jcmd "$pid" Thread.print -l > "$tmpdir/thread.txt"
grep -A 12 '"hot-loop-demo"' "$tmpdir/thread.txt"
